# Demo5 changed cells: (14,0),(17,0) on left edge; (21,4),(22,4),(24,4) on right edge; (26,3) bottom edge.
# All are ON the bbox outline of markers (bbox rows12-26 cols0-4). So f works for demo5 too! But my earlier submission used exactly that... yet wrong.
# Wait — maybe my earlier test submission was judged wrong because I filled ONLY border cells but some expected cells INSIDE? No wait, maybe the correct interpretation is opposite: paint bg cells that lie between two markers along a row/col across the WHOLE grid, where "between" includes passing out of the rectangle? Test both variants on demos and find one matching all 5.
def seg_fill_all(g,mk,bg):
    pts=[(i,j) for i,r_ in enumerate(g) for j,x in enumerate(r_) if x==mk]
    out=[row[:] for row in g]; used=set()
    for idx,pA in enumerate(pts):
        for pB in pts[idx+1:]:
            if pA[0]==pB[0]:
                lo,hi=sorted((pA[1],pB[1]))
                # only fill strictly inside bbox bounds relative to this pair's span within bbox columns? Use: fill between them if both markers are bbox border/corners... simpler: fill between any collinear marker pair IF at least one of the segments lies inside bbox. Actually just: fill between them if min(lo,hi)>c0 or max(lo,hi)<c1? try variants.
                cells=[(pA[0],j) for j in range(lo+1,hi)]
            elif pA[1]==pB[1]:
                lo,hi=sorted((pA[0],pB[0]))
                cells=[(i,pA[1]) for i in range(lo+1,hi)]
            else: continue
            # keep only cells inside bbox (strictly interior or border?) - variant A: strictly interior
            ia=lambda c: r0<c<r1 and c0<c<c1
            ib=lambda c: r0<=c<=r1 and c0<=c<=c1
            for c in cells:
                if ia(c) or ib(c): used.add((c[0],c[1]))
