def perim_pts(gi,mk):
    H,W=len(gi),len(gi[0])
    pts=[(a_,x_) for a_ in range(H) for x_ in range(W) if gi[a_][x_]==mk]
    rs=sorted({r for r,c in pts}); cs=sorted({c for r,c in pts})
    minr,maxr,minc,maxc=min(rs),max(rs),min(cs),max(cs)
    return {(a_,x_) for a_ in range(minr,maxr+1) for x_ in (minc,maxc)}|{(r,x_) for r in (minr,maxr) for x_ in range(minc,maxc+1)}-{p for p in perim_pts(gi,mk) for p in [p]}
